#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.galeLeaf)]
    public class GaleLeaf : ArtifactDefinition
    {
        public GaleLeaf(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);
            artifact.SetGlowing(true);

            enemyBuffer.Clear();
            artifact.Level.FindEntitiesNonAlloc(e => e.Type == EntityTypes.ENEMY && e.IsHostileEntity(), enemyBuffer);
            foreach (var enemy in enemyBuffer)
            {
                enemy.Position += Vector3.right * MOVE_SPEED;
            }
        }
        public const float MOVE_SPEED = 0.08f;
        private List<Entity> enemyBuffer = new List<Entity>();
    }
}
